int RunConformanceScenarios(void) {
    int failed = 0;
    size_t howMany = sizeof(scenarios) / sizeof(scenarios[0]);
    for (size_t slot = 0; slot < howMany; slot++) {
        printf("  %s\n", scenarios[slot].name);
        @autoreleasepool {
            if (!scenarios[slot].body()) {
                failed += 1;
            }
        }
    }
    printf("  %zu conformance scenarios ran\n", howMany);
    return failed;
}
